// src/pages/404.tsx
import * as React from "react";
import type { HeadFC, PageProps } from "gatsby";
import { graphql } from "gatsby";
import { useTranslation } from "gatsby-plugin-react-i18next";
import  Link  from "../components/AppLink";
import Layout from "../components/Layout";
import data from "../data/data.json";
import type { Company } from "../interfaces";
import images from "../images";
import SEO from "../components/seo";
import { useEffect } from "react";

const info: Company = (data as Company[])[0];

const NotFoundPage: React.FC<PageProps> = () => {
  const { t } = useTranslation();

  useEffect(() => {
    document.body.style.backgroundImage = `url(${images.bg.src})`;
    document.body.style.backgroundSize = "cover";
    document.body.style.backgroundPosition = "center";
    document.body.style.backgroundRepeat = "no-repeat";

    return () => {
      document.body.style.backgroundImage = "";
      document.body.style.backgroundSize = "";
      document.body.style.backgroundPosition = "";
      document.body.style.backgroundRepeat = "";
    };
  }, []);

  return (
    <Layout data={info} bgImage={images.bg_carousel_1?.src}>
      <SEO
        data={info}
        titleKey="notFound.metaTitle"
        descriptionKey="notFound.metaDescription"
        pathname="/404/"
        noindex
        schemaType="Organization"
      />

      <main className="mx-auto max-w-4xl px-4 sm:px-6 py-14 text-center">
        <p className="text-sm sm:text-base text-light/70">{t("notFound.kicker")}</p>

        <h1 className="mt-3 text-3xl sm:text-6xl poppins-bold text-light">
          {t("notFound.title")}
        </h1>

        <p className="mt-6 text-lg sm:text-2xl text-light/90 mx-auto max-w-3xl">
          {t("notFound.subtitle")}
        </p>

        <div className="my-10 flex flex-col sm:flex-row gap-3 items-center justify-center">
          <Link
            to="/"
            className="rounded-full bg-secondary px-6 py-3 text-light text-center hover:opacity-90 transition"
          >
            {t("notFound.cta.home")}
          </Link>

          <Link
            to="/services/"
            className="rounded-full bg-purplesemilight px-6 py-3 text-light text-center hover:opacity-90 transition"
          >
            {t("notFound.cta.services")}
          </Link>

          <a
            href={info.whatsapp}
            target="_blank"
            rel="noreferrer"
            className="rounded-full bg-purplelight px-6 py-3 text-secondary text-center hover:opacity-90 transition"
          >
            {t("notFound.cta.help")}
          </a>
        </div>

        <section className={styles.card}>
          <h2 className="text-lg font-semibold text-light/90">
            {t("notFound.card.title")}
          </h2>

          <ul className="mt-4 space-y-2 text-sm sm:text-base text-light/70 leading-relaxed">
            <li>• {t("notFound.card.bullets.0")}</li>
            <li>• {t("notFound.card.bullets.1")}</li>
            <li>• {t("notFound.card.bullets.2")}</li>
          </ul>
        </section>

        <p className="mt-10 text-xs sm:text-sm text-light/70">
          {t("notFound.footerNote")}
        </p>
      </main>
    </Layout>
  );
};

export default NotFoundPage;

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

const styles = {
  sectionWrapper:
    "border-2 w-full sm:w-[1024px] mx-auto rounded-xl p-2 sm:p-8 mt-8 bg-darkBg/50",
  labelTitle: "text-2xl sm:text-4xl text-center poppins-regular text-verde",
  container: "mx-auto w-full max-w-6xl px-4 sm:px-6",
  card: "rounded-2xl border border-black/10 bg-primary/70 p-5 shadow-sm supports-[backdrop-filter]:bg-purplesemilight/40 supports-[backdrop-filter]:backdrop-blur text-light",
  cardTitle: "text-base sm:text-lg font-semibold text-light/90",
  cardText: "mt-3 text-sm sm:text-base text-light/70 leading-relaxed",
};
